	@Test
	void explicitReadDatasetExcludesCatalogGraphs() {
		String query = "SELECT ?v { GRAPH :G { BIND(1 AS ?v) } }";
		SimpleDataset empty = new SimpleDataset();
		empty.setExplicitReadDataset(true);
		assertThat(evaluate(query, strategy(empty, null))).isEmpty();

		SimpleDataset onlyOther = new SimpleDataset();
		onlyOther.addNamedGraph(OTHER_GRAPH);
		assertThat(evaluate(query, strategy(onlyOther, null))).isEmpty();
	}

	@Test
	void oneOriginalUuidIsSharedAcrossOuterOccurrences() {
		List<BindingSet> rows = evaluate("SELECT ?k ?u { VALUES ?k { 1 2 } GRAPH :G { BIND(UUID() AS ?u) } }",
				strategy(null, null));
		assertThat(rows).extracting(row -> row.getValue("k")).containsExactlyInAnyOrder(ONE, TWO);
		assertThat(rows).extracting(row -> row.getValue("u")).containsOnly(rows.getFirst().getValue("u"));
		assertThat(rows.getFirst().getValue("u")).isInstanceOf(IRI.class);
	}

	@Test
	void structurallyEqualGraphOperandsStillAllocateDistinctUuids() {
		assertThat(evaluate("SELECT ?u { GRAPH :G { BIND(UUID() AS ?u) } GRAPH :G { BIND(UUID() AS ?u) } }",
				strategy(null, null))).isEmpty();
	}

	@Test
	void oneVolatilePredicateChoiceAppliesToBothOuterOccurrences() {
		AtomicInteger calls = new AtomicInteger();
		DefaultEvaluationStrategy strategy = reference(new DefaultEvaluationStrategy(emptyCatalog(), null) {
			@Override
			public QueryValueEvaluationStep prepare(FunctionCall call, QueryEvaluationContext context) {
				if (SCRIPTED_PREDICATE.equals(call.getURI())) {
					return bindings -> VF.createLiteral(calls.getAndIncrement() == 0);
				}
				return super.prepare(call, context);
			}
		});
		assertThat(evaluate(
				"SELECT ?k { VALUES ?k { 1 2 } GRAPH :G { FILTER(<" + SCRIPTED_PREDICATE + ">()) } }", strategy))
						.containsExactlyInAnyOrder(row(Map.of("k", ONE)), row(Map.of("k", TWO)));
		assertThat(calls).hasValue(1);
	}

	@Test
	void reducedDeliversOneCoherentMultiplicityAcrossOuterOccurrences() {
		List<BindingSet> rows = evaluate("SELECT ?k ?x { VALUES ?k { 1 2 } GRAPH :G { "
				+ "{ SELECT REDUCED ?x { VALUES ?x { :a :a } } } } }", strategy(null, null));
		long oneCount = rows.stream().filter(row -> ONE.equals(row.getValue("k"))).count();
		long twoCount = rows.stream().filter(row -> TWO.equals(row.getValue("k"))).count();
		assertThat(oneCount).isBetween(1L, 2L).isEqualTo(twoCount);
		assertThat(rows).allSatisfy(row -> assertThat(row.getValue("x")).isEqualTo(A));
	}

	@Test
	void blankNodeIdentityBelongsToEachOriginalOccurrence() {
		List<BindingSet> rows = evaluate("SELECT ?k ?b { VALUES ?k { 1 2 } "
				+ "GRAPH :G { VALUES ?seed { :a :a } BIND(BNODE() AS ?b) } }", strategy(null, null));
		List<Value> forOne = rows.stream()
				.filter(row -> ONE.equals(row.getValue("k")))
				.map(row -> row.getValue("b"))
				.toList();
		List<Value> forTwo = rows.stream()
				.filter(row -> TWO.equals(row.getValue("k")))
				.map(row -> row.getValue("b"))
				.toList();
		assertThat(forOne).hasSize(2)
				.doesNotHaveDuplicates()
				.allSatisfy(value -> assertThat(value).isInstanceOf(BNode.class));
		assertThat(forTwo).containsExactlyInAnyOrderElementsOf(forOne);
	}

	@Test
	void fatalServiceIsDemandedEvenWhenGraphJoinCannotProduceARow() {
		FederatedServiceResolver failing = endpoint -> {
			throw new QueryEvaluationException("controlled required SERVICE failure");
		};
		String remoteBody = "<urn:gbj:remote> { ?s :p ?o }";
		String join = "SELECT ?g { VALUES ?g { :missing } GRAPH ?g { SERVICE %s " + remoteBody + " } }";
		assertThatThrownBy(() -> evaluate(join.formatted(""), strategy(null, failing)))
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("controlled required SERVICE failure");
		assertThat(evaluate(join.formatted("SILENT"), strategy(null, failing))).isEmpty();

		String silent = "SELECT ?g { VALUES ?g { :G } GRAPH ?g { SERVICE SILENT " + remoteBody + " } }";
		assertThat(evaluate(silent, strategy(null, failing))).containsExactly(row(Map.of("g", GRAPH)));
	}

	private static DefaultEvaluationStrategy strategy(Dataset dataset, FederatedServiceResolver resolver) {
		return reference(new DefaultEvaluationStrategy(emptyCatalog(), dataset, resolver));
	}

	private static DefaultEvaluationStrategy reference(DefaultEvaluationStrategy strategy) {
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT
				.withGraphRestrictionMode(GraphRestrictionMode.FORCE_INDEPENDENT));
		return strategy;
	}

	private static EmptyTripleSource emptyCatalog() {
		return new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Resource> getContextIDs() {
				return new SingletonIteration<>(GRAPH);
			}
		};
	}

	private static List<BindingSet> evaluate(String query, DefaultEvaluationStrategy strategy) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + query, null)
				.getTupleExpr();
		try (CloseableIteration<BindingSet> results = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(results);
		}
	}

	private static MapBindingSet row(Map<String, Value> entries) {
		MapBindingSet result = new MapBindingSet(entries.size());
		entries.forEach(result::addBinding);
		return result;
	}

	private static Value integer(int value) {
		return VF.createLiteral(Integer.toString(value), XSD.INTEGER);
	}

	private record GraphCase(String name, String sparql, List<BindingSet> expected) {
	}
